const type = $json.command_type;

let route = "unknown";

if (type === "menu") {
  route = "menu";
} else if (type === "report") {
  route = "report";
} else if (type === "ask_range") {
  route = "ask_range";
}

return [{
  json: {
    ...$json,
    route
  }
}];

const items = $input.all();
const results = [];

for (const item of items) {

  let action = item.json.text || '';
  let chat_id = item.json.chat_id || $env.TELEGRAM_CHAT_ID;

  action = action.trim().toLowerCase();

  let numDays = 0;
  let offset = 0;

  // Báo cáo preset
  if (action === 'báo cáo hôm nay') {
    numDays = 1;
    offset = 0;
  }

  else if (action === 'báo cáo hôm qua') {
    numDays = 1;
    offset = 1;
  }

  else if (action === 'báo cáo 7 ngày') {
    numDays = 7;
    offset = 1;
  }

  else if (action === 'báo cáo 30 ngày') {
    numDays = 30;
    offset = 1;
  }

  // Báo cáo khoảng YYYY-MM-DD -> YYYY-MM-DD
  else if (action.startsWith('báo cáo từ ')) {

    const m = action.match(
      /(\d{4}-\d{2}-\d{2}).*?(\d{4}-\d{2}-\d{2})/
    );

    if (m) {

      const d1 = new Date(m[1]);
      const d2 = new Date(m[2]);

      const diff =
        Math.abs(d2 - d1) / (1000 * 60 * 60 * 24) + 1;

      let c = new Date(Math.min(d1, d2));

      let dates = [];

      for (let i = 0; i < diff; i++) {
        dates.push(c.toISOString().split('T')[0]);
        c.setDate(c.getDate() + 1);
      }

      return [{
        json: {
          route: 'report',
          chat_id,
          dates,
          is_batch: dates.length > 2
        }
      }];
    }
  }

  // Báo cáo dạng: báo cáo 24/03
  else {

    const shortDateMatch = action.match(
      /^báo cáo (\d{1,2})\/(\d{1,2})$/
    );

    if (shortDateMatch) {

      const day = shortDateMatch[1].padStart(2, '0');
      const month = shortDateMatch[2].padStart(2, '0');

      const currentYear = new Date().getFullYear();

      const targetDate =
        `${currentYear}-${month}-${day}`;

      return [{
        json: {
          route: 'report',
          chat_id,
          dates: [targetDate],
          is_batch: false
        }
      }];
    }
  }

  // Preset reports
  if (numDays > 0) {

    let dates = [];

    let endDate = new Date();

    endDate.setDate(
      endDate.getDate() - offset
    );

    let startDate = new Date(endDate);

    startDate.setDate(
      startDate.getDate() - numDays + 1
    );

    let c = new Date(startDate);

    while (c <= endDate) {

      dates.push(
        c.toISOString().split('T')[0]
      );

      c.setDate(c.getDate() + 1);
    }

    return [{
      json: {
        route: 'report',
        chat_id,
        dates,
        is_batch: dates.length > 2
      }
    }];
  }
}

return [];

const values = $("Đọc Google Sheet").first().json.values || [];

function isHeaderRow(row) {
  const first = String(row?.[0] ?? '').trim().toLowerCase();
  const second = String(row?.[1] ?? '').trim().toLowerCase();
  return first === 'ma_quang_cao' || first === 'mã quảng cáo' || second === 'ngay' || second === 'ngày';
}

function toNumber(value) {
  const raw = String(value ?? '').trim();
  if (!raw || raw === '#VALUE!') return 0;
  const normalized = raw.replace(/\./g, '').replace(',', '.');
  const n = Number(normalized);
  return Number.isFinite(n) ? n : 0;
}

const rows = values.filter((row, index) => !(index === 0 && isHeaderRow(row)));
const records = rows.map((row) => ({
  ma_quang_cao: row?.[0] ?? '',
  ngay: row?.[1] ?? '',
  chien_dich: row?.[2] ?? '',
  ten_quang_cao: row?.[3] ?? '',
  chi_tieu: toNumber(row?.[4]),
  nguoi_tiep_can: toNumber(row?.[5]),
  ngan_sach: toNumber(row?.[6]),
  click: toNumber(row?.[7]),
  mess_comment: toNumber(row?.[8]),
  khach_sai_tep: toNumber(row?.[9]),
  khach_hop_le: toNumber(row?.[10]),
  sdt: toNumber(row?.[11]),
  khach_chot: toNumber(row?.[12]),
  chi_phi_tren_khach_hop_le: toNumber(row?.[13]),
  chi_phi_khach_tren_sdt: toNumber(row?.[14]),
  chi_phi_khach_chot: toNumber(row?.[15]),
  ghi_chu: row?.[16] ?? '',
  trang_thai: row?.[17] ?? '',
  key: row?.[18] ?? '',
  thoi_diem_cap_nhat: row?.[19] ?? '',
}));

return [{ json: { records, rowCount: records.length } }];

const records = $("Normalize Sheet Data").first().json.records || [];
const datesToReport = $("Parse & Route").first().json.dates || [];
const chat_id = $("Parse & Route").first().json.chat_id;

function normalizeDate(value) {
  const raw = String(value ?? '').trim();
  const dmy = raw.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (dmy) {
    const [, d, m, y] = dmy;
    return `${y}-${m.padStart(2, '0')}-${d.padStart(2, '0')}`;
  }
  return raw;
}

const dateSet = new Set(datesToReport.map(normalizeDate));
const loadedRecords = records.filter((r) => r.ngay && dateSet.has(normalizeDate(r.ngay)));

return [{ json: { datesToReport, loadedRecords, chat_id } }];

const { loadedRecords, chat_id, datesToReport } = $input.first().json;
let totalSpend = 0; let totalLeads = 0;
for (const r of loadedRecords) {
  totalSpend += Number(r.chi_tieu || 0);
  totalLeads += Number(r.khach_hop_le || 0);
}
const totalCPA = totalLeads > 0 ? totalSpend / totalLeads : 0;
let msg = `📊 *BÁO CÁO META ADS*\n📅 Ngày: ${datesToReport.join(', ')}\n💰 Tổng chi tiêu: *${totalSpend.toLocaleString('vi-VN')}đ*\n📩 Tổng kết quả: *${totalLeads}*\n🎯 CPA: *${Math.round(totalCPA).toLocaleString('vi-VN')}đ*`;
return [{ json: { message: msg, chat_id } }];

const result = $input.first().json.result || [];
const staticData = $getWorkflowStaticData('global');

console.log('DEBUG: result.length =', result.length);
console.log('DEBUG: staticData before =', JSON.stringify(staticData));

const update = result.length > 0 ? result[result.length - 1] : null;

if (!update) {
  console.log('DEBUG: No update found, returning []');
  return [];
}

const updateId = update.update_id.toString();

if (staticData.processed_ids && staticData.processed_ids[updateId]) {
  console.log('DEBUG: Already processed updateId', updateId);
  return [];
}

if (!staticData.processed_ids) {
  staticData.processed_ids = {};
}

staticData.processed_ids[updateId] = true;
staticData.last_update_id = update.update_id + 1;

const msg = update.message || update.callback_query?.message;

if (!msg) {
  console.log('DEBUG: No message in update');
  return [];
}

const text = (msg.text || update.callback_query?.data || '')
  .trim()
  .toLowerCase();

const chat_id = msg.chat?.id || update.callback_query?.from?.id;

if (!text || !chat_id) {
  console.log('DEBUG: No text or chat_id found');
  return [];
}

// Duplicate command protection
// Same user + same command within 10s → skip
const dedupeKey = `${chat_id}_${text}`;
const now = Date.now();

if (!staticData.dedupe) {
  staticData.dedupe = {};
}

const lastSeen = staticData.dedupe[dedupeKey] || 0;

if (now - lastSeen < 10000) {
  console.log('DEBUG: Duplicate command skipped', dedupeKey);
  return [];
}

staticData.dedupe[dedupeKey] = now;

let command_type = 'unknown';

const menuCmds = [
  '/start',
  'menu',
  'báo cáo'
];

const reportCmds = [
  'báo cáo hôm nay',
  'báo cáo hôm qua',
  'báo cáo 7 ngày',
  'báo cáo 30 ngày'
];

if (menuCmds.includes(text)) {
  command_type = 'menu';
}
else if (
  reportCmds.includes(text)
  || text.startsWith('báo cáo từ ')
  || /^báo cáo \d{1,2}\/\d{1,2}$/.test(text)
) {
  command_type = 'report';
}
else if (text === 'chọn khoảng ngày') {
  command_type = 'ask_range';
}
else {
  command_type = 'unknown';
}

console.log(
  'DEBUG: Successfully processing updateId',
  updateId,
  'type',
  command_type
);

return [{
  json: {
    text,
    chat_id,
    command_type,
    update_id: update.update_id
  }
}];
